import csv
import io
from decimal import Decimal

def summarize(source):
    totals={}
    for row in csv.DictReader(io.StringIO(source)):
        region=row["region"]
        totals[region]=totals.get(region,Decimal(0))+Decimal(row["amount"])
    return {key:format(value,".2f") for key,value in totals.items()}

