from datetime import datetime, timezone

def as_utc(text):
    value=datetime.fromisoformat(text)
    if value.tzinfo is None: return value.replace(tzinfo=timezone.utc)
    return value.astimezone(timezone.utc)

ttl-cache.cache.py:
class TTLCache:
    def __init__(self, clock):
        self.clock=clock
        self.values={}

    def set(self,key,value,ttl):
        if ttl <= 0:
            self.values.pop(key,None)
        else:
            self.values[key]=(value,self.clock()+ttl)

    def get(self,key,default=None):
        if key not in self.values: return default
        value,deadline=self.values[key]
        if self.clock() >= deadline:
            del self.values[key]
            return default
        return value

dependency-order.graph.py:
import heapq

def dependency_order(graph):
    nodes=set(graph) | {d for deps in graph.values() for d in deps}
    deps={node:set(graph.get(node,[])) for node in nodes}
    followers={node:set() for node in nodes}
    for node,needs in deps.items():
        for need in needs: followers[need].add(node)
    ready=[node for node in nodes if not deps[node]]
    heapq.heapify(ready)
    result=[]
    while ready:
        node=heapq.heappop(ready)
        result.append(node)
        for follower in followers[node]:
            deps[follower].remove(node)
            if not deps[follower]: heapq.heappush(ready,follower)
    if len(result)!=len(nodes): raise ValueError("cycle")
    return result

